public Account(String accountNumber, double balance) {
    this.accountNumber = accountNumber;
    this.balance = balance;
}

public void deposit(double amount) {
    if (amount > 0) {
        balance += amount;
        System.out.println("Deposited: N" + amount + ". New Balance: N" + balance);
    }
}

public double getBalance() {
    return balance;
}

// Class 2: Savings Account
class SavingsAccount extends Account {
    private static final double MIN_THRESHOLD = 1000.0;

public SavingsAccount(String accountNumber, double balance) {
    super(accountNumber, balance);
}

@Override
public boolean withdraw(double amount) {
    if ((balance - amount) >= MIN_THRESHOLD) {
        balance -= amount;
        System.out.println("Withdrawal successful. New Balance: N" + balance);
        return true;
    } else {
        System.out.println("Withdrawal failed. Minimum threshold of N" + MIN_THRESHOLD + " must be maintained.");
        return false;
    }
}

// Class 3: Checking Account
class CheckingAccount extends Account {
    private static final double OVERDRAFT_FEE = 50.0;

public CheckingAccount(String accountNumber, double balance) {
    super(accountNumber, balance);
}

@Override
public boolean withdraw(double amount) {
    balance -= amount;
    System.out.println("Withdrew: N" + amount);
    if (balance < 0) {
        balance -= OVERDRAFT_FEE;
        System.out.println("Account overdrawn. Overdraft fee of N" + OVERDRAFT_FEE + " applied.");
    }
    System.out.println("New Balance: N" + balance);
    return true;
}

